{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the packing plan — are we minimizing the number of containers used, maximizing the total weight (or units) of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If it turns out that not all goods can be packed into containers that satisfy the rules (for example, the D requirement of 12 units per container limits how many containers can be opened), is it acceptable to leave some goods unshipped, or must every available unit of every type be packed?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice between leaving goods unshipped or packing all available units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The 12-units-of-D-per-container rule applies to every container that is used, right — including containers that hold only D and other types, with no exception for containers that happen to carry no A?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the scope of a specific rule, with no other independent requests."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule \"if a container contains any type A then it must also contain at least one type C\" — does this mean at least 1 unit of C, or is there a larger minimum number of C units required when A is present?"
  ],
  "rationale": "The response asks for a single specific clarification regarding the minimum quantity of type C required, presenting a binary choice between 1 unit and a larger number."
}

{
  "action": "question",
  "question_count": 1,
